{"command":"python - <<'PY'
import json
from pathlib import Path
src = Path('vllm/attention/ops/triton_unified_attention.py').read_text().splitlines()

def extract(name):
    start = None
    indent = None
    for i,l in enumerate(src):
        if l.startswith(f'def {name}(') or l.startswith(f'@triton.jit') and i+1 < len(src) and src[i+1].startswith(f'def {name}('):
            start = i if src[i].startswith('@triton.jit') else i
            break
    if start is None:
        raise ValueError(name)
    if src[start].startswith('@triton.jit'):
        body_start = start
        sig_i = start+1
    else:
        body_start = start
        sig_i = start
    base_indent = len(src[sig_i]) - len(src[sig_i].lstrip())
    end = len(src)
    for j in range(sig_i+1, len(src)):
        line = src[j]
        if line.startswith('def ') or line.startswith('@triton.jit'):
            if len(line) - len(line.lstrip()) == 0:
                end = j
                break
    return '\n'.join(src[body_start:end]).rstrip()

obj = {
  'vllm/attention/ops/triton_unified_attention.py': {
    'kernel_unified_attention_2d': extract('kernel_unified_attention_2d'),
    'unified_attention': extract('unified_attention'),
  }
}
Path('/prediction.json').write_text(json.dumps(obj, indent=4))
print(Path('/prediction.json').read_text())
PY"}

